using Hyper.Domain.Entities.Integrations; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; namespace Hyper.Infrastructure.Data.Configurations; public sealed class IntegrationEventAuditConfiguration:IEntityTypeConfiguration<IntegrationEventAudit>{public void Configure(EntityTypeBuilder<IntegrationEventAudit>b){b.ToTable("IntegrationEventAudits");b.HasKey(x=>x.Id);b.Property(x=>x.Direction).HasMaxLength(20).IsRequired();b.Property(x=>x.EventType).HasMaxLength(200).IsRequired();b.Property(x=>x.ExternalEventId).HasMaxLength(200).IsRequired();b.Property(x=>x.PayloadHash).HasMaxLength(128).IsRequired();b.Property(x=>x.CorrelationId).HasMaxLength(100);b.HasIndex(x=>new{x.ConnectionId,x.ExternalEventId,x.Direction}).IsUnique();}}
